    fn import_book(&mut self, path: PathBuf) {
        if !is_supported_book(&path) {
            self.notice = format!("No reconozco el formato de {}", path.file_name().unwrap_or_default().to_string_lossy());
            return;
        }
        let source = path.to_string_lossy().to_string();
        if self.books.iter().any(|book| book.file_path.as_deref() == Some(source.as_str())) {
            self.notice = "Ese libro ya está en la biblioteca".to_owned();
            return;
        }
        let metadata = read_book_metadata(&path);
        let title = metadata.get("title").cloned().filter(|value| !value.is_empty())
            .or_else(|| path.file_stem().map(|name| name.to_string_lossy().to_string()))
            .unwrap_or_else(|| "Libro sin título".to_owned());
        let id = self.books.iter().map(|book| book.id).max().unwrap_or(0) + 1;
        let book = Book {
            id, title,
            author: metadata.get("author").cloned().unwrap_or_default(),
            year: metadata.get("year").cloned().unwrap_or_default(),
            description: metadata.get("description").cloned().unwrap_or_default(),
            tags: metadata.get("tags").map(|tags| tags.split(',').map(str::trim).filter(|tag| !tag.is_empty()).map(str::to_owned).collect()).unwrap_or_default(),
            topic: String::new(), file_path: Some(source),
        };
        self.books.push(book);
        self.selected = Some(id);
        self.save();
        self.start_classification(id);
        self.notice = "Libro añadido; preparando su clasificación".to_owned();
    }

    fn start_classification(&mut self, book_id: u64) {
        let api_key = load_api_key(&self.classify_provider);
        if api_key.is_empty() {
            self.ai_status = "Configura primero la clave de Gemini o Groq.".to_owned();
            self.settings_open = true;
            return;
        }
        let Some(book) = self.books.iter().find(|book| book.id == book_id).cloned() else { return; };
        let provider = self.classify_provider.clone();
        let sender = self.task_sender.clone();
        self.ai_status = format!("Clasificando «{}» con {}…", book.title, provider);
        std::thread::spawn(move || {
            let result = classify_with_ai(&book, &provider, &api_key);
            let _ = sender.send(AiTaskResult { book_id, result });
        });
    }

    fn receive_classifications(&mut self) {
        while let Ok(task) = self.task_receiver.try_recv() {
            match task.result {
                Ok((topic, tags)) => {
                    if let Some(book) = self.books.iter_mut().find(|book| book.id == task.book_id) {
                        book.topic = topic;
                        for tag in tags {
                            if !book.tags.iter().any(|existing| existing.eq_ignore_ascii_case(&tag)) {
                                book.tags.push(tag);
                            }
                        }
                        self.ai_status = format!("Clasificación y etiquetas actualizadas para «{}»", book.title);
                        self.save();
                    }
                }
                Err(error) => self.ai_status = format!("No se pudo clasificar: {error}"),
            }
        }
    }
}

