fn classify_with_fallback(
    book: &Book,
    gemini_key: &str,
    groq_key: &str,
) -> Result<(String, Vec<String>), String> {
    if !gemini_key.is_empty() {
        match classify_with_ai(book, "Gemini", gemini_key) {
            Ok(result) => return Ok(result),
            Err(gemini_error) => {
                if !groq_key.is_empty() {
                    match classify_with_ai(book, "Groq", groq_key) {
                        Ok(result) => return Ok(result),
                        Err(groq_error) => {
                            return Err(format!("Gemini falló ({gemini_error}); Groq también falló ({groq_error})"));
                        }
                    }
                }
                return Err(format!("Gemini falló ({gemini_error}); no hay clave de Groq configurada"));
            }
        }
    }

    if !groq_key.is_empty() {
        return classify_with_ai(book, "Groq", groq_key)
            .map_err(|groq_error| format!("Gemini no tiene clave configurada; Groq falló ({groq_error})"));
    }

    Err("No hay claves de Gemini ni Groq configuradas".to_owned())
}

